// HELPER: Create rounded rect with bevel geometry
// ─────────────────────────────────────────────────────────
function createRoundedRectWithBevel(width, height, radius, bevelDepth) {
  const shape = new THREE.Shape();

  // Outline rounded rectangle
  const halfW = width / 2;
  const halfH = height / 2;

  shape.moveTo(-halfW + radius, -halfH);
  shape.lineTo(halfW - radius, -halfH);
  shape.quadraticCurveTo(halfW, -halfH, halfW, -halfH + radius);
  shape.lineTo(halfW, halfH - radius);
  shape.quadraticCurveTo(halfW, halfH, halfW - radius, halfH);
  shape.lineTo(-halfW + radius, halfH);
  shape.quadraticCurveTo(-halfW, halfH, -halfW, halfH - radius);
  shape.lineTo(-halfW, -halfH + radius);
  shape.quadraticCurveTo(-halfW, -halfH, -halfW + radius, -halfH);

  const extrudeSettings = {
    depth: bevelDepth,
    bevelEnabled: true,
    bevelThickness: bevelDepth * 0.5,
    bevelSize: bevelDepth * 0.4,
    bevelSegments: 3,
  };

  const geom = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geom.center();

  return geom;
}
